root=Path(__file__).resolve().parents[1]/'client/lib/l10n'
for index,lang in enumerate(['ru','en']):
    file=root/f'app_{lang}.arb';data=json.loads(file.read_text(encoding='utf-8-sig'))
    data.update({key:values[index] for key,values in strings.items()})
    file.write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
